
const page = document.body.dataset.page;
const icon = (name, className = "") => '<i data-lucide="' + name + '" class="' + className + '"></i>';
const link = (href, label, name, active = false) => '<a class="nav-link ' + (active ? 'is-active' : '') + '" href="' + href + '">' + icon(name) + '<span>' + label + '</span></a>';
const pill = (label, kind = '') => '<span class="tag ' + kind + '">' + label + '</span>';
const button = (label, kind = 'btn-secondary', attrs = '') => '<button class="btn ' + kind + '" ' + attrs + '>' + label + '</button>';

const pageMeta = {
  dashboard: ['Dashboard', 'Your learning space'], classroom: ['Junior classroom', 'Ava\'s class space'], lesson: ['B1 lesson', 'B1 / Workplace communication'], practice: ['Adaptive practice', 'Practice'], speaking: ['Speaking gym', 'Practice'], tutors: ['Live tutoring', 'Coaching'], progress: ['Progress', 'Learning record'], reports: ['Reports', 'Learning record'], certificates: ['Certificates', 'Learning record'], parent: ['Family dashboard', 'Parent'], teacher: ['Teacher workspace', 'Educator'], school: ['School overview', 'Organisation'], studio: ['Studio', 'Content'], account: ['Account', 'Settings']
};

function brand() {
  return '<a class="brand" href="index.html" aria-label="IELPS home"><span class="brand-mark">' + icon('book-open') + '</span><span class="brand-word">I<em>E</em>LPS</span></a>';
}

function pip() {
  return '<aside class="pip-panel" id="pip-panel" hidden><h3>Ask Pip</h3><p>Find the next lesson, practice a skill, or open your report.</p><div class="pip-actions"><a href="lesson.html">Continue B1 lesson</a><a href="practice.html">Start adaptive practice</a><a href="progress.html">Open learning record</a></div></aside><button class="pip" id="pip-toggle" aria-expanded="false" aria-controls="pip-panel"><span class="pip-mark">' + icon('sparkles') + '</span><span>Ask Pip</span></button>';
}

function publicHeader() {
  return '<header class="public-topbar"><div class="public-topbar__inner">' + brand() + '<nav class="top-links" aria-label="Main navigation"><a href="index.html#paths">Learning paths</a><a href="practice.html">Practice</a><a href="tutors.html">Live tutoring</a><a href="certificates.html">Certificates</a></nav><div class="header-actions"><a class="btn btn-quiet" href="dashboard.html">Sign in</a><a class="btn btn-primary" href="register.html">Start free</a></div></div></header>';
}

function publicFooter() {
  return '<footer class="footer"><div class="footer__inner"><div>' + brand() + '</div><span>English Integrated Language Platform</span><span>Review build, August 2026</span></div></footer>';
}

function shell(content) {
  const meta = pageMeta[page] || ['IELPS', ''];
  const active = page === 'dashboard' ? 'dashboard' : page;
  const nav = [
    ['Overview', 'dashboard.html', 'dashboard', 'layout-dashboard'],
    ['Lessons', 'lesson.html', 'lesson', 'book-open'],
    ['Practice', 'practice.html', 'practice', 'brain-circuit'],
    ['Speaking', 'speaking.html', 'speaking', 'mic'],
    ['Live tutoring', 'tutors.html', 'tutors', 'messages-square'],
    ['Progress', 'progress.html', 'progress', 'chart-no-axes-combined'],
    ['Certificates', 'certificates.html', 'certificates', 'badge-check']
  ];
  const roleNav = [
    ['Parent view', 'parent.html', 'parent', 'heart-handshake'],
    ['Teacher view', 'teacher.html', 'teacher', 'presentation'],
    ['School view', 'school.html', 'school', 'building-2'],
    ['Studio', 'studio.html', 'studio', 'pen-tool']
  ];
  const navRows = nav.map((n) => link(n[1], n[0], n[3], active === n[2])).join('');
  const roleRows = roleNav.map((n) => link(n[1], n[0], n[3], active === n[2])).join('');
  return '<div class="app-layout"><aside class="sidebar">' + brand() + '<div class="role-chip">' + icon('graduation-cap') + '<span>Adult learner workspace</span></div><div class="nav-group"><div class="nav-group-title">Learn</div>' + navRows + '</div><div class="nav-group"><div class="nav-group-title">Other pathways</div>' + roleRows + '</div><div class="sidebar-bottom">' + link('account.html', 'Account', 'settings', active === 'account') + '<a class="nav-link" href="index.html" data-toast="You have signed out and returned home.">' + icon('log-out') + '<span>Sign out</span></a></div></aside><div class="app-frame"><header class="app-header"><div class="app-header__inner"><div class="crumb">' + icon('home') + '<span>IELPS</span>' + icon('chevron-right') + '<strong>' + meta[0] + '</strong></div><div class="header-actions"><div class="header-progress"><span>B1 route</span><div class="meter bar"><span style="width:62%"></span></div><span>62%</span></div>' + button(icon('play') + ' Continue', 'btn btn-primary', 'data-toast="Opening your next lesson."') + '</div></div></header><main class="main">' + content + '</main><nav class="mobile-nav" aria-label="Mobile navigation">' + link('dashboard.html','Home','layout-dashboard',active === 'dashboard') + link('lesson.html','Learn','book-open',active === 'lesson') + link('practice.html','Practice','brain-circuit',active === 'practice') + link('progress.html','Progress','chart-no-axes-combined',active === 'progress') + link('account.html','Account','settings',active === 'account') + '</nav></div></div>' + pip();
}

function pageTop(title, detail, actions = '') { return '<div class="page-top"><div><h1>' + title + '</h1><p>' + detail + '</p></div><div class="page-actions">' + actions + '</div></div>'; }
function stat(label, value, kind) { return '<div class="status-stat ' + kind + '"><small>' + label + '</small><strong>' + value + '</strong></div>'; }
function lessonRow(number, title, meta, tag, kind = '') { return '<div class="lesson-row"><span class="lesson-index">' + number + '</span><div><h3>' + title + '</h3><p>' + meta + '</p></div>' + pill(tag, kind) + '</div>'; }
function today(iconName, name, detail, action) { return '<div class="today-item">' + icon(iconName) + '<div><b>' + name + '</b><small>' + detail + '</small></div>' + action + '</div>'; }
function chart(values) { return '<div class="chart">' + values.map((v, i) => '<div class="chart-bar" style="height:' + v + '%"><span>W' + (i + 1) + '</span></div>').join('') + '</div><div class="chart-legend"><span>Weekly learning time</span><b>+18% this month</b></div>'; }

