  return shell(pageTop('Good afternoon, Jordan', 'Your B1 route is ready. One short session keeps your plan moving.', button(icon('calendar-days') + ' View plan', 'btn-secondary', 'data-toast="Weekly plan opened."')) + '<div class="main-grid"><div class="stack"><section class="action-panel"><span class="eyebrow" style="color:#ffc373">Next on your route</span><h2>Give clear instructions at work.</h2><p>Build practical phrases for meetings, handovers and polite clarification. Your current session takes about 16 minutes.</p><div class="action-meta"><span>Lesson 4 of 18</span><span>Listening + speaking</span><span>16 min</span></div><a class="btn btn-primary" href="lesson.html">Resume lesson ' + icon('arrow-right') + '</a></section><section class="status-rail">' + stat('Course progress', '62%', 'teal') + stat('Weekly goal', '3/4', 'coral') + stat('Review due', '8', 'violet') + stat('Study streak', '6 days', 'gold') + '</section><section class="surface surface-pad"><div class="surface-head"><div><h2>Course queue</h2><p>One thing at a time. The engine keeps the order useful.</p></div><a href="lesson.html">Open course</a></div>' + lessonRow('04', 'Give clear instructions', 'B1 workplace communication · 16 min', 'Continue', 'coral') + lessonRow('05', 'Clarify and confirm', 'B1 workplace communication · 14 min', 'Next', 'teal') + lessonRow('06', 'Handle a simple problem', 'B1 workplace communication · 18 min', 'Later', 'violet') + '</section></div><aside class="stack"><section class="surface surface-pad"><div class="quick-progress"><div class="progress-ring" style="--value:62" data-label="62%"></div><div><h3>B1 progress</h3><p>12 lessons remain before your B2 check.</p><a class="btn btn-small btn-secondary" href="progress.html">See progress</a></div></div></section><section class="surface surface-pad"><div class="surface-head"><h3>Today</h3><a href="practice.html">Adjust</a></div><div class="today-list">' + today('brain-circuit', 'Smart review', '8 items · 6 min', '<a class="btn btn-small btn-secondary" href="practice.html">Start</a>') + today('mic', 'Speak aloud', 'One guided turn · 5 min', '<a class="btn btn-small btn-secondary" href="speaking.html">Open</a>') + today('headphones', 'Listen back', 'Recap audio · 3 min', '<a class="btn btn-small btn-secondary" href="lesson.html">Play</a>') + '</div></section><section class="surface surface-pad"><div class="surface-head"><h3>Live support</h3><a href="tutors.html">View slots</a></div><p>Two speaking sessions are available in your preferred study window.</p><a class="btn btn-small btn-teal" href="tutors.html">Find a session</a></section></aside></div>');
