document.getElementById('app').innerHTML = (renderers[page] || landing)();
document.title = page === 'index' ? 'IELPS | Learn English' : (pageMeta[page]?.[0] || 'IELPS Review') + ' | IELPS';
if (window.lucide) window.lucide.createIcons();

const toast = document.getElementById('toast');
let toastTimer;
function showToast(message) { toast.textContent = message; toast.classList.add('is-visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('is-visible'), 3200); }
document.addEventListener('click', (event) => {
  const toastTarget = event.target.closest('[data-toast]');
  if (toastTarget) showToast(toastTarget.dataset.toast);
  const filter = event.target.closest('[data-filter]');
  if (filter) { filter.parentElement.querySelectorAll('[data-filter]').forEach((item) => item.classList.remove('is-selected')); filter.classList.add('is-selected'); }
  const answer = event.target.closest('[data-answer]');
  if (answer) { answer.parentElement.querySelectorAll('[data-answer]').forEach((item) => item.classList.remove('is-selected')); answer.classList.add('is-selected'); }
  const slot = event.target.closest('[data-slot]');
  if (slot) { slot.parentElement.querySelectorAll('[data-slot]').forEach((item) => item.classList.remove('is-selected')); slot.classList.add('is-selected'); }
  const role = event.target.closest('[data-role]');
  if (role) { role.parentElement.querySelectorAll('[data-role]').forEach((item) => item.classList.remove('is-selected')); role.classList.add('is-selected'); }
  const toggle = event.target.closest('.toggle');
  if (toggle) { toggle.classList.toggle('is-on'); toggle.setAttribute('aria-label', toggle.classList.contains('is-on') ? 'Enabled' : 'Disabled'); }
  const pipToggle = event.target.closest('#pip-toggle');
  if (pipToggle) { const panel = document.getElementById('pip-panel'); const isOpen = panel.hasAttribute('hidden'); panel.toggleAttribute('hidden', !isOpen); pipToggle.setAttribute('aria-expanded', String(isOpen)); }
});
